+
+    public void testToXContent_CreateTheRightFormatForASingleChatCompletionResult() {
+        String resultContent = "content";
+        var result = new ChatCompletionResults(List.of(new ChatCompletionResults.Result(resultContent)));
+
+        assertThat(
