+        UserGroupInformation.setConfiguration(cfg);
+
+        MiniDFSCluster.Builder builder = new MiniDFSCluster.Builder(cfg);
+        // if(isSecure()) {
+        builder.nameNodePort(explicitPort);
+        // } else {
+        // builder.nameNodePort(explicitPort);
+        // }
+        if (isHA()) {
